pub async fn broadcast<T>(socks: &AsyncSocks, val: &T)
where
	T: serde::Serialize,
{
	if let Ok(valstr) = serde_json::to_string(val) {
		let msg = Message::text(valstr);
		for sock in socks.read().await.values() {
			sock.tx.send(msg.clone()).ok();
		}
	}
}

